// Nakshatra offline cache — generated by tools/polish_web.py.
// Everything the game needs is static; this worker makes the second visit work
// without a network. The cache name changes whenever the PCK changes.
const VERSION = 'nakshatra-197ea03845';
const ASSETS = [
  'index.html',
  'index.js',
  'index.wasm',
  'index.pck?v=197ea03845',
  'index.audio.worklet.js',
  'index.audio.position.worklet.js',
  'index.icon.png',
  'index.apple-touch-icon.png',
  'index.png',
  'manifest.webmanifest'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(VERSION)
      .then((cache) => cache.addAll(ASSETS))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys
        .filter((key) => key.startsWith('nakshatra-') && key !== VERSION)
        .map((key) => caches.delete(key))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith(
    caches.match(request, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      return fetch(request).then((response) => {
        if (response && response.ok) {
          const copy = response.clone();
          caches.open(VERSION).then((cache) => cache.put(request, copy));
        }
        return response;
      }).catch(() => {
        if (request.mode === 'navigate') {
          return caches.match('index.html');
        }
        return new Response('', { status: 503, statusText: 'Offline' });
      });
    })
  );
});
